-- 1. Define the target group (a named set of databases, not 'everything on the server')
EXEC jobs.sp_add_target_group 'TenantDatabases';

EXEC jobs.sp_add_target_group_member
    @target_group_name = 'TenantDatabases',
    @target_type = 'SqlDatabase',
    @refresh_credential_name = 'JobCredential',
    @server_name = 'sql-tenants-prod.database.windows.net',
    @database_name = 'TenantA';

EXEC jobs.sp_add_target_group_member
    @target_group_name = 'TenantDatabases',
    @target_type = 'SqlDatabase',
    @refresh_credential_name = 'JobCredential',
    @server_name = 'sql-tenants-prod.database.windows.net',
    @database_name = 'TenantB';

-- 2. Define the job and its step
EXEC jobs.sp_add_job
    @job_name = 'NightlyUpdateStatistics',
    @description = 'Update statistics on every tenant database nightly';

EXEC jobs.sp_add_jobstep
    @job_name = 'NightlyUpdateStatistics',
    @command = N'EXEC sp_updatestats;',
    @credential_name = 'JobCredential',
    @target_group_name = 'TenantDatabases';

-- 3. Schedule it
EXEC jobs.sp_update_job
    @job_name = 'NightlyUpdateStatistics',
    @enabled = 1,
    @schedule_interval_type = 'Days',
    @schedule_interval_count = 1,
    @schedule_start_time = '2026-10-10 02:00:00';

-- Set the blocked process threshold (in seconds) at the instance level first
EXEC sp_configure 'blocked process threshold', 5;
RECONFIGURE;

-- Create the Extended Events session
CREATE EVENT SESSION CaptureBlockingReports
ON SERVER
ADD EVENT sqlserver.blocked_process_report(
    ACTION (sqlserver.sql_text, sqlserver.session_id, sqlserver.database_name)
)
ADD TARGET package0.ring_buffer(
    SET max_memory = 4096
)
WITH (
    MAX_DISPATCH_LATENCY = 5 SECONDS,
    TRACK_CAUSALITY = ON
);

-- Start the session
ALTER EVENT SESSION CaptureBlockingReports ON SERVER STATE = START;

-- Query the ring buffer target for captured blocking events
SELECT
    CAST(target_data AS XML) AS BlockingXml
FROM sys.dm_xe_session_targets st
JOIN sys.dm_xe_sessions s ON s.address = st.event_session_address
WHERE s.name = 'CaptureBlockingReports'
  AND st.target_name = 'ring_buffer';

$resourceGroup = "rg-prod-sql"
$serverName    = "sql-orders-prod"
$restorePoint  = (Get-Date).AddHours(-1)  # restore to 1 hour ago as a drill

$databases = Get-AzSqlDatabase -ResourceGroupName $resourceGroup -ServerName $serverName |
    Where-Object { $_.DatabaseName -ne "master" }

$results = foreach ($db in $databases) {
    $tempName = "$($db.DatabaseName)_drtest_$(Get-Date -Format 'yyyyMMddHHmm')"

    try {
        $restored = Restore-AzSqlDatabase `
            -FromPointInTimeBackup `
            -PointInTime $restorePoint `
            -ResourceGroupName $resourceGroup `
            -ServerName $serverName `
            -TargetDatabaseName $tempName `
            -ResourceId $db.ResourceId `
            -ErrorAction Stop

        # Basic sanity check: restored database exists and is online
        $check = Get-AzSqlDatabase -ResourceGroupName $resourceGroup -ServerName $serverName -DatabaseName $tempName
        $success = ($check.Status -eq 'Online')

        [PSCustomObject]@{
            Database     = $db.DatabaseName
            RestoreOK    = $success
            RestoredName = $tempName
            Error        = $null
        }
    }
    catch {
        [PSCustomObject]@{
            Database     = $db.DatabaseName
            RestoreOK    = $false
            RestoredName = $tempName
            Error        = $_.Exception.Message
        }
    }
    finally {
        # Always attempt cleanup, even if the restore or check failed partway
        Remove-AzSqlDatabase -ResourceGroupName $resourceGroup -ServerName $serverName -DatabaseName $tempName -ErrorAction SilentlyContinue -Force
    }
}

$results | Format-Table Database, RestoreOK, Error -AutoSize

if ($results | Where-Object { -not $_.RestoreOK }) {
    Write-Warning "One or more databases FAILED the point-in-time restore drill. Review before relying on PITR for these."
}
